<?php
declare(strict_types=1);

// Página de reportes.
// Reúne el progreso de actividades según el rol del usuario y permite exportar CSV.
require __DIR__.'/../includes/auth.php';require_login();require_once __DIR__.'/../config/database.php';
$me=$_SESSION['user'];$uid=(int)$me['id'];$role=(string)$me['role'];$today=date('Y-m-d');$from=trim((string)($_GET['desde']??date('Y-m-d',strtotime('-30 days'))));$to=trim((string)($_GET['hasta']??$today));
foreach(['from'=>$from,'to'=>$to] as $key=>$date){$d=DateTime::createFromFormat('!Y-m-d',$date);if(!$d||$d->format('Y-m-d')!==$date){http_response_code(422);exit('Fechas inválidas.');}}
if($from>$to||strtotime($to)-strtotime($from)>366*86400){http_response_code(422);exit('El rango debe ser de máximo un año.');}
$rows=[];$title='Reporte académico';$params=[$from.' 00:00:00',$to.' 23:59:59'];
if($role==='student'){$title='Mi progreso por asignatura';$q=$pdo->prepare('SELECT s.name subject,COUNT(*) attempts,SUM(a.is_correct) correct,COALESCE(SUM(a.duration_seconds),0) seconds FROM activity_attempts a JOIN questions q ON q.id=a.question_id JOIN topics t ON t.id=q.topic_id JOIN academic_competencies c ON c.id=t.competency_id JOIN subjects s ON s.id=c.subject_id WHERE a.student_id=? AND a.created_at BETWEEN ? AND ? GROUP BY s.id ORDER BY s.name');$q->execute([$uid,...$params]);$rows=$q->fetchAll();}
elseif($role==='parent'){$title='Progreso de estudiantes vinculados';$q=$pdo->prepare("SELECT u.name student,s.name subject,COUNT(*) attempts,SUM(a.is_correct) correct,COALESCE(SUM(a.duration_seconds),0) seconds FROM parent_student_relationships r JOIN users u ON u.id=r.student_id AND r.status='active' JOIN activity_attempts a ON a.student_id=u.id JOIN questions q ON q.id=a.question_id JOIN topics t ON t.id=q.topic_id JOIN academic_competencies c ON c.id=t.competency_id JOIN subjects s ON s.id=c.subject_id WHERE r.parent_id=? AND a.created_at BETWEEN ? AND ? GROUP BY u.id,s.id ORDER BY u.name,s.name");$q->execute([$uid,...$params]);$rows=$q->fetchAll();}
elseif($role==='teacher'){$title='Avance de mis grupos';$group=(int)($_GET['grupo']??0);$q=$pdo->prepare('SELECT g.id,g.name FROM teacher_groups g WHERE g.teacher_id=? ORDER BY g.name');$q->execute([$uid]);$groups=$q->fetchAll();$validIds=array_map(fn($x)=>(int)$x['id'],$groups);if($group&&!in_array($group,$validIds,true)){http_response_code(403);exit('Grupo no autorizado.');}$sql='SELECT g.name group_name,u.name student,s.name subject,COUNT(a.id) attempts,COALESCE(SUM(a.is_correct),0) correct,COALESCE(SUM(a.duration_seconds),0) seconds FROM teacher_groups g JOIN group_students gs ON gs.group_id=g.id JOIN users u ON u.id=gs.student_id LEFT JOIN activity_attempts a ON a.student_id=u.id AND a.created_at BETWEEN ? AND ? LEFT JOIN questions q ON q.id=a.question_id LEFT JOIN topics t ON t.id=q.topic_id LEFT JOIN academic_competencies c ON c.id=t.competency_id LEFT JOIN subjects s ON s.id=c.subject_id WHERE g.teacher_id=?';$bind=[...$params,$uid];if($group){$sql.=' AND g.id=?';$bind[]=$group;}$sql.=' GROUP BY g.id,u.id,s.id ORDER BY g.name,u.name,s.name';$q=$pdo->prepare($sql);$q->execute($bind);$rows=$q->fetchAll();}
elseif(in_array($role,['admin','superadmin'],true)){$title='Actividad agregada';$q=$pdo->prepare('SELECT u.grade_level,s.name subject,COUNT(a.id) attempts,COALESCE(SUM(a.is_correct),0) correct,COALESCE(SUM(a.duration_seconds),0) seconds FROM users u JOIN activity_attempts a ON a.student_id=u.id JOIN questions q ON q.id=a.question_id JOIN topics t ON t.id=q.topic_id JOIN academic_competencies c ON c.id=t.competency_id JOIN subjects s ON s.id=c.subject_id WHERE a.created_at BETWEEN ? AND ? GROUP BY u.grade_level,s.id ORDER BY u.grade_level,s.name');$q->execute($params);$rows=$q->fetchAll();}
else{http_response_code(403);exit('Rol no autorizado.');}
if(($_GET['export']??'')==='csv'){
 if(!function_exists('csrf_token')||!hash_equals(csrf_token(),(string)($_GET['csrf']??''))){http_response_code(403);exit('Token de exportación inválido.');}
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="prossor-reporte-'.$from.'-'.$to.'.csv"');$out=fopen('php://output','wb');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,array_keys($rows[0]??['mensaje'=>'Sin datos para el periodo']));foreach($rows as $row)fputcsv($out,array_values($row));fclose($out);exit;
}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reportes · Prossor AI</title><link rel="stylesheet" href="../assets/css/app.css"></head><body class="app-body"><main class="main-content"><header class="topbar"><a href="dashboard.php">← Mi espacio</a><b>Reportes</b></header><section class="welcome"><div><p class="eyebrow">DATOS REGISTRADOS</p><h1><?= h($title) ?></h1><p class="muted">Resultados basados en intentos guardados; fecha, zona del servidor.</p></div></section><section class="panel"><form method="get" class="chat-form"><label>Desde<input type="date" name="desde" value="<?= h($from) ?>" required></label><label>Hasta<input type="date" name="hasta" value="<?= h($to) ?>" required></label><?php if($role==='teacher'): ?><label>Grupo<select name="grupo"><option value="0">Todos mis grupos</option><?php foreach($groups as $g): ?><option value="<?= (int)$g['id'] ?>" <?= (int)($_GET['grupo']??0)===(int)$g['id']?'selected':'' ?>><?= h($g['name']) ?></option><?php endforeach; ?></select></label><?php endif; ?><button class="button light">Filtrar</button></form><?php if($rows): ?><div class="table-wrap"><table><thead><tr><?php foreach(array_keys($rows[0]) as $key): ?><th><?= h(ucfirst(str_replace('_',' ',$key))) ?></th><?php endforeach; ?><th>Porcentaje</th><th>Minutos</th></tr></thead><tbody><?php foreach($rows as $row): $pct=(int)$row['attempts']?round((int)$row['correct']*100/(int)$row['attempts']):0; ?><tr><?php foreach($row as $value): ?><td><?= h((string)$value) ?></td><?php endforeach; ?><td><?= $pct ?>%</td><td><?= (int)round((int)$row['seconds']/60) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="stats-grid"><?php foreach($rows as $row): $pct=(int)$row['attempts']?round((int)$row['correct']*100/(int)$row['attempts']):0; $label=$row['subject']??$row['student']??('Grado '.($row['grade_level']??'')); ?><article class="stat-card"><span><?= h((string)$label) ?></span><strong><?= $pct ?>%</strong><div style="height:8px;background:#e9edf5;border-radius:8px"><span style="display:block;width:<?= $pct ?>%;height:8px;background:#5369dc;border-radius:8px"></span></div><small><?= (int)$row['attempts'] ?> intentos registrados</small></article><?php endforeach; ?></div><form method="get"><input type="hidden" name="desde" value="<?= h($from) ?>"><input type="hidden" name="hasta" value="<?= h($to) ?>"><?php if($role==='teacher'): ?><input type="hidden" name="grupo" value="<?= (int)($_GET['grupo']??0) ?>"><?php endif; ?><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><button class="button primary" name="export" value="csv">Descargar CSV</button></form><?php else: ?><p class="muted">No hay intentos para el rango seleccionado.</p><?php endif; ?></section></main></body></html>
